/* Find char index by codepoint, returns -1 if not found */
static inline int cjk_find(unsigned int cp) {
  int lo=0, hi=CJK_FONT_N-1;
  while(lo<=hi) {
    int mid=(lo+hi)/2;
    if(CJK_CODEPOINTS[mid]==cp) return mid;
    if(CJK_CODEPOINTS[mid]<cp) lo=mid+1; else hi=mid-1;
  }
  return -1;
}

